try{if($_SERVER['REQUEST_METHOD']==='POST'){csrf();if(($_POST['action']??'')==='link'){$service->linkBusiness($_POST);header('Location: usuarios.php?linked=1',true,303);exit;}if(($_POST['action']??'')==='set_status'){$accountId=(int)($_POST['account_id']??0);$status=(string)($_POST['status']??'');$service->setAccountStatus($accountId,$status,isset($_SESSION['admin_account_id'])?(int)$_SESSION['admin_account_id']:null,(string)($_POST['reason']??''));header('Location: usuarios.php?status='.rawurlencode($status),true,303);exit;}if(($_POST['action']??'')==='reset_password'){$accountId=(int)($_POST['account_id']??0);$token=(new AccountPasswordResetService(db()))->issue($accountId,'admin');$_SESSION['admin_generated_password_link']=site_path('/negocios/cambiar-clave/').'?token='.rawurlencode($token);header('Location: usuarios.php?reset_link=1',true,303);exit;}throw new RuntimeException('Acción no válida. Las cuentas se crean desde el registro empresarial; aquí puedes vincular negocios aprobados, cambiar su acceso o generar un enlace seguro de contraseña.');}}
